mapper.select:
SELECT
FROM
ORDER BY id DESC LIMIT #{offset}, #{size}

SELECT a.labelName, a.totalCount, ROUND(a.totalCount * 100.0 / NULLIF(b.totalCount, 0), 2) AS ratio, a.avgSocialHours, a.avgSleepHours, a.avgStress, a.avgAnxiety, a.avgAddiction, a.avgAcademicPerformance FROM ( SELECT CASE WHEN depression_label = 1 THEN '存在风险' WHEN depression_label = 0 THEN '暂无明显风险' ELSE '未知' END AS labelName, COUNT(1) AS totalCount, ROUND(IFNULL(AVG(daily_social_media_hours), 0), 2) AS avgSocialHours, ROUND(IFNULL(AVG(sleep_hours), 0), 2) AS avgSleepHours, ROUND(IFNULL(AVG(stress_level), 0), 2) AS avgStress, ROUND(IFNULL(AVG(anxiety_level), 0), 2) AS avgAnxiety, ROUND(IFNULL(AVG(addiction_level), 0), 2) AS avgAddiction, ROUND(IFNULL(AVG(academic_performance), 0), 2) AS avgAcademicPerformance FROM
GROUP BY depression_label ) a CROSS JOIN ( SELECT COUNT(1) AS totalCount FROM
) b ORDER BY a.totalCount DESC

SELECT a.labelName, a.totalCount, ROUND(a.totalCount * 100.0 / NULLIF(b.totalCount, 0), 2) AS ratio, a.riskRate, a.avgSocialHours, a.avgSleepHours FROM ( SELECT IFNULL(NULLIF(gender, ''), '未知') AS labelName, COUNT(1) AS totalCount, ROUND(SUM(CASE WHEN depression_label = 1 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(1), 0), 2) AS riskRate, ROUND(IFNULL(AVG(daily_social_media_hours), 0), 2) AS avgSocialHours, ROUND(IFNULL(AVG(sleep_hours), 0), 2) AS avgSleepHours FROM
GROUP BY IFNULL(NULLIF(gender, ''), '未知') ) a CROSS JOIN ( SELECT COUNT(1) AS totalCount FROM
) b ORDER BY a.totalCount DESC

SELECT a.labelName, a.totalCount, ROUND(a.totalCount * 100.0 / NULLIF(b.totalCount, 0), 2) AS ratio, a.avgSocialHours, a.avgSleepHours, a.avgScreenBeforeSleep, a.avgAcademicPerformance, a.avgStress, a.avgAnxiety, a.avgAddiction, a.riskRate FROM ( SELECT IFNULL(NULLIF(platform_usage, ''), '未知平台') AS labelName, COUNT(1) AS totalCount, ROUND(IFNULL(AVG(daily_social_media_hours), 0), 2) AS avgSocialHours, ROUND(IFNULL(AVG(sleep_hours), 0), 2) AS avgSleepHours, ROUND(IFNULL(AVG(screen_time_before_sleep), 0), 2) AS avgScreenBeforeSleep, ROUND(IFNULL(AVG(academic_performance), 0), 2) AS avgAcademicPerformance, ROUND(IFNULL(AVG(stress_level), 0), 2) AS avgStress, ROUND(IFNULL(AVG(anxiety_level), 0), 2) AS avgAnxiety, ROUND(IFNULL(AVG(addiction_level), 0), 2) AS avgAddiction, ROUND(SUM(CASE WHEN depression_label = 1 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(1), 0), 2) AS riskRate FROM
GROUP BY IFNULL(NULLIF(platform_usage, ''), '未知平台') ) a CROSS JOIN ( SELECT COUNT(1) AS totalCount FROM
) b ORDER BY a.totalCount DESC LIMIT 12
